import * as THREE from 'three';
import {OrbitControls} from 'three/addons/controls/OrbitControls.js';
import {decodeFile,voxelPoints,slicePixels} from './nifti.js';
const $=id=>document.getElementById(id),host=$('scene');
const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(33,1,.1,100);
let imageState=null,publishedCase=false;
let renderer,controls,scan=null,real=false,xray=false,loading=false,loadSequence=0,demo=null,current=null,markerPoint=new THREE.Vector3(),markerNormal=new THREE.Vector3();
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,3500);}
function resetCamera(){camera.position.set(8.3,4.0,3.8);controls?.target.set(0,0,0);controls?.update();}
function setCurrent(group){if(current)scene.remove(current);current=group;if(group)scene.add(group);}
function materialState(){current?.traverse(o=>{if(o.material){o.material.transparent=xray;o.material.opacity=xray?.3:1;o.material.depthWrite=!xray;}});}
function dispose(group){group?.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});}
try{
 renderer=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;host.appendChild(renderer.domElement);
 // Matte tissue with soft self-shadowing and neutral fill.
 renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
 scene.add(new THREE.AmbientLight(0xfff4f1,.68));
 const key=new THREE.DirectionalLight(0xfff8f3,1.9);key.position.set(-3,6,5);key.castShadow=true;key.shadow.mapSize.set(2048,2048);key.shadow.camera.left=-3;key.shadow.camera.right=3;key.shadow.camera.top=3;key.shadow.camera.bottom=-3;key.shadow.camera.near=1;key.shadow.camera.far=20;key.shadow.normalBias=.018;key.shadow.bias=-.0001;key.shadow.radius=3;key.shadow.intensity=.78;scene.add(key);
 controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;controls.enablePan=false;controls.minDistance=4;controls.maxDistance=18;controls.autoRotate=false;controls.autoRotateSpeed=.45;resetCamera();
 new ResizeObserver(()=>{const w=host.clientWidth,h=host.clientHeight;camera.aspect=w/h;camera.updateProjectionMatrix();renderer.setSize(w,h);}).observe(host);
 renderer.setAnimationLoop(()=>{if(document.hidden)return;controls.update();renderer.render(scene,camera);});
 renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('sceneError').textContent='The 3D graphics context was interrupted. Reload this page to restore the viewer.';$('sceneError').hidden=false;});
 loadAnatomy();
}catch(e){$('sceneError').hidden=false;$('sceneError').textContent='The 3D viewer needs WebGL2. Try an updated browser with hardware acceleration enabled. MRI slice viewing is still available.';$('geometryState').textContent='3D unavailable';}
async function loadAnatomy(){
 try{const buffers=await Promise.all(['left','right'].map(async side=>{const r=await fetch(`assets/${side}.bin`);if(!r.ok)throw Error('Mesh unavailable');return r.arrayBuffer();}));const geometries=buffers.map(b=>{const d=new DataView(b),n=d.getUint32(0,true),m=d.getUint32(4,true),g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(new Float32Array(b,8,n),3));g.setIndex(new THREE.BufferAttribute(new Uint32Array(b,8+n*4,m),1));return g;});
 const box=new THREE.Box3();for(const g of geometries){g.computeBoundingBox();box.union(g.boundingBox);}const center=box.getCenter(new THREE.Vector3()),scale=4/Math.max(...box.getSize(new THREE.Vector3()).toArray());demo=new THREE.Group();
 for(const g of geometries){const p=g.attributes.position;for(let i=0;i<p.count;i++){const x=(p.getX(i)-center.x)*scale,y=(p.getZ(i)-center.z)*scale,z=-(p.getY(i)-center.y)*scale;p.setXYZ(i,x,y,z);}g.computeVertexNormals();g.computeBoundingSphere();const colors=new Float32Array(p.count*3),pink=new THREE.Color(0xdfa0b1),blue=new THREE.Color(0x315aff);const target=new THREE.Vector3(1,.55,.55);let nearest=Infinity;for(let i=0;i<p.count;i++){const v=new THREE.Vector3().fromBufferAttribute(p,i),dist=v.distanceTo(target);if(dist<nearest){nearest=dist;if(g===geometries[1]){markerPoint.copy(v);markerNormal.fromBufferAttribute(g.attributes.normal,i);}}const col=dist<.25?blue:pink;colors[i*3]=col.r;colors[i*3+1]=col.g;colors[i*3+2]=col.b;}if(g===geometries[1]){for(let i=0;i<p.count;i++){const v=new THREE.Vector3().fromBufferAttribute(p,i),col=v.distanceTo(markerPoint)<.28?blue:pink;colors[i*3]=col.r;colors[i*3+1]=col.g;colors[i*3+2]=col.b;}}g.setAttribute('color',new THREE.BufferAttribute(colors,3));const mesh=new THREE.Mesh(g,new THREE.MeshStandardMaterial({vertexColors:true,roughness:.94,metalness:0,emissive:0x10090c,emissiveIntensity:.12,side:THREE.DoubleSide,flatShading:false}));mesh.castShadow=true;mesh.receiveShadow=true;demo.add(mesh);}
 // Blue vertex colors provide the pickable demonstration region.
 if(!real){setCurrent(demo);materialState();}$('geometryState').textContent=real?'LOCAL VOLUME':'REFERENCE MODEL';
 }catch(e){$('geometryState').textContent='Anatomy unavailable';$('sceneError').hidden=false;$('sceneError').textContent='The reference model could not load. Check your connection and reload. You can still open a NIfTI scan.';}
}
function tab(upload){if(upload)hideDetails();$('uploadPanel').hidden=!upload;$('finding').hidden=upload;for(const [id,active] of [['scanTab',upload],['demoTab',!upload]]){$(id).classList.toggle('active',active);$(id).setAttribute('aria-selected',String(active));}}
function showDemo(){hideDetails();showImage(false);if(current&&current!==demo)dispose(current);real=false;setCurrent(demo);materialState();$('mode').textContent='REFERENCE ANATOMY · DEMO';$('viewLabel').textContent='Cortical surface';$('geometryState').textContent=demo?'REFERENCE MODEL':'Loading anatomy…';$('geometryNote').textContent='Two hemispheres. One remarkable organ.';document.querySelector('.orientation>span').textContent='REFERENCE MODEL';$('slices').hidden=true;tab(false);resetCamera();}
let pinned=false,hoverTimer,hoverFrame,lastPick=0,press=null;
function details(pin=true){if(real||current!==demo)return;clearTimeout(hoverTimer);if(pin)pinned=true;$('detail').hidden=false;$('finding').querySelector('.lead').hidden=true;$('explore').hidden=true;}
function hideDetails(){clearTimeout(hoverTimer);pinned=false;$('detail').hidden=true;$('finding').querySelector('.lead').hidden=false;$('explore').hidden=false;}
function deferHide(){clearTimeout(hoverTimer);if(!pinned)hoverTimer=setTimeout(()=>{if(!pinned)hideDetails();},180);}
$('explore').onclick=()=>details(true);$('closeDetail').onclick=hideDetails;
$('detail').onmouseenter=()=>clearTimeout(hoverTimer);$('detail').onmouseleave=deferHide;
const regionRay=new THREE.Raycaster(),pointer=new THREE.Vector2();
function regionAt(x,y){if(real||current!==demo||!renderer)return false;const rect=renderer.domElement.getBoundingClientRect();pointer.set((x-rect.left)/rect.width*2-1,-(y-rect.top)/rect.height*2+1);regionRay.setFromCamera(pointer,camera);const hit=regionRay.intersectObjects(demo.children,false)[0];if(!hit?.face)return false;const c=hit.object.geometry.attributes.color;return [hit.face.a,hit.face.b,hit.face.c].some(i=>c.getZ(i)>c.getX(i)*1.4);}
if(renderer){const canvas=renderer.domElement;canvas.tabIndex=0;canvas.setAttribute('aria-label','3D brain viewer. Drag to rotate. Hover or click the blue region for details; Enter opens the example; Escape closes it.');canvas.addEventListener('pointerdown',e=>{press={x:e.clientX,y:e.clientY};});canvas.addEventListener('pointerup',e=>{if(press&&Math.hypot(e.clientX-press.x,e.clientY-press.y)<6&&regionAt(e.clientX,e.clientY)){if(pinned)hideDetails();else details(true);}press=null;});canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||e.buttons)return;cancelAnimationFrame(hoverFrame);hoverFrame=requestAnimationFrame(()=>{if(performance.now()-lastPick<70)return;lastPick=performance.now();const over=regionAt(e.clientX,e.clientY);host.style.cursor=over?'pointer':'grab';if(over)details(false);else deferHide();});});canvas.addEventListener('pointerleave',()=>{host.style.cursor='grab';deferHide();});canvas.addEventListener('keydown',e=>{if(e.key==='Enter'&&!real){e.preventDefault();details(true);}if(e.key==='Escape')hideDetails();});}
$('demoTab').onclick=showDemo;$('scanTab').onclick=()=>{tab(true);if(imageState){real=true;presentImage();}else if(scan){real=true;renderVolume();setupSlices();}};
$('uploadTop').onclick=()=>{$('scanTab').click();$('workspace').scrollIntoView({behavior:'smooth'});};
for(const id of ['about','limits','privacy'])$(id).onclick=()=>$('info').showModal();$('closeInfo').onclick=()=>$('info').close();$('info').addEventListener('click',e=>{if(e.target===$('info')){const r=$('info').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('info').close();}});
$('rotate').onclick=()=>{if(!controls)return;controls.autoRotate=!controls.autoRotate;$('rotate').setAttribute('aria-pressed',String(controls.autoRotate));};$('reset').onclick=()=>{if(real&&imageState){resetImage();}else resetCamera();};
$('layer').onclick=()=>{xray=!xray;materialState();$('layer').setAttribute('aria-pressed',String(xray));};
$('snap').onclick=()=>{if(real&&imageState){exportImage();return;}if(!renderer)return toast('3D export is unavailable in this browser.');renderer.render(scene,camera);renderer.domElement.toBlob(blob=>{if(!blob)return toast('Unable to export this view.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.download=real?'cortex-voxel-preview.png':'cortex-reference-anatomy.png';a.href=url;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('3D view exported as PNG.');});};
async function load(file){if(!file)return;exitPublishedCase();const request=++loadSequence;tab(true);loading=true;$('status').classList.remove('error');$('status').textContent='Opening your file locally…';$('drop').setAttribute('aria-busy','true');try{await new Promise(r=>setTimeout(r,20));if(!/\.(nii(\.gz)?|png|jpe?g|webp)$/i.test(file.name))throw Error('Choose a NIfTI (.nii/.nii.gz), PNG, JPG, or WebP file.');if(/\.(png|jpe?g|webp)$/i.test(file.name)){await loadImage(file,request);return;}const parsed=await decodeFile(file);if(request!==loadSequence)return;clearImage();showImage(false);scan=parsed;real=true;$('filename').textContent=file.name;$('scanActions').hidden=false;$('threshold').value=35;renderVolume();setupSlices();$('status').textContent=`${scan.dims.join(' × ')} voxels · ${scan.spacing.map(x=>Number(x.toFixed(2))).join(' × ')} spacing units. Loaded locally. No medical findings generated.`;resetCamera();}catch(e){if(request!==loadSequence)return;$('status').textContent=e.message||'Unable to open this file.';$('status').classList.add('error');}finally{if(request===loadSequence){loading=false;$('drop').removeAttribute('aria-busy');$('file').value='';}}}
function renderVolume(){if(!scan)return;const points=voxelPoints(scan,Number($('threshold').value));if(renderer){if(current&&current!==demo)dispose(current);const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(points,3));const group=new THREE.Group();group.add(new THREE.Points(g,new THREE.PointsMaterial({color:0xe0aab7,size:.04,sizeAttenuation:true})));setCurrent(group);materialState();}$('mode').textContent='YOUR VOLUME · NO AUTOMATED FINDINGS';$('viewLabel').textContent='MRI / Thresholded voxels';$('geometryState').textContent='LOCAL VOLUME';$('geometryNote').textContent=points.length?`${(points.length/3).toLocaleString()} sampled voxels · stored voxel orientation`:'No voxels above this threshold. Lower the slider.';document.querySelector('.orientation>span').textContent='VOXEL PREVIEW';$('thresholdValue').textContent=$('threshold').value+'%';}
function setupSlices(){$('slices').hidden=false;for(const [i,axis] of ['x','y','z'].entries()){const slider=$(axis+'Slice');slider.min=0;slider.max=scan.dims[i]-1;slider.value=Math.floor(scan.dims[i]/2);}drawSlices();}
function drawSlices(){if(!scan)return;for(const [i,axis] of ['x','y','z'].entries()){const n=Number($(axis+'Slice').value),p=slicePixels(scan,i,n,Number($('contrast').value)),canvas=$('slice'+axis.toUpperCase());const source=document.createElement('canvas');source.width=p.width;source.height=p.height;source.getContext('2d').putImageData(new ImageData(p.data,p.width,p.height),0,0);canvas.width=Math.max(1,Math.round(512*Math.min(1,p.ratio)));canvas.height=Math.max(1,Math.round(512/Math.max(1,p.ratio)));const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.drawImage(source,0,0,canvas.width,canvas.height);$(axis+'Value').textContent=`${n+1} / ${scan.dims[i]}`;}}
$('threshold').oninput=()=>{cancelAnimationFrame(renderVolume.frame);renderVolume.frame=requestAnimationFrame(renderVolume);};for(const axis of ['x','y','z'])$(axis+'Slice').oninput=drawSlices;$('contrast').oninput=drawSlices;
$('showSlices').onclick=()=>$('slices').scrollIntoView({behavior:'smooth'});$('clear').onclick=()=>{++loadSequence;clearImage();showImage(false);scan=null;loading=false;$('scanActions').hidden=true;$('slices').hidden=true;$('status').classList.remove('error');$('status').textContent='Scan removed from this tab. Choose another volume whenever you’re ready.';$('filename').textContent='';$('file').value='';for(const axis of ['X','Y','Z']){const c=$('slice'+axis);c.getContext('2d').clearRect(0,0,c.width,c.height);}showDemo();tab(true);toast('Scan cleared from memory.');};
$('file').onchange=e=>load(e.target.files[0]);$('drop').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('file').click();}};$('drop').ondragover=e=>{e.preventDefault();$('drop').classList.add('dragging');};$('drop').ondragleave=()=>$('drop').classList.remove('dragging');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('dragging');if(e.dataTransfer.files.length!==1){$('status').textContent='Choose one volume or image at a time.';return;}load(e.dataTransfer.files[0]);};

function showImage(visible){$('viewHint').textContent=visible?'USE THE IMAGE CONTROLS TO ADJUST YOUR VIEW':'DRAG TO ROTATE · SCROLL TO ZOOM';$('snap').setAttribute('aria-label',visible?'Export image as PNG':'Export 3D view as PNG');host.style.visibility=visible?'hidden':'visible';$('imageStage').hidden=!visible;if(controls)controls.enabled=!visible;for(const id of ['rotate','layer'])$(id).disabled=visible;}
function clearImage(){exitPublishedCase();if(imageState?.url)URL.revokeObjectURL(imageState.url);imageState=null;$('imagePreview').removeAttribute('src');$('imageActions').hidden=true;}
function resetImage(){for(const id of ['imageBrightness','imageContrast','imageZoom'])$(id).value=100;updateImage();}
function updateImage(){const b=$('imageBrightness').value,c=$('imageContrast').value,z=Number($('imageZoom').value)/100;$('imagePreview').style.filter='brightness('+b+'%) contrast('+c+'%)';$('imagePreview').style.transform='scale('+z+')';$('brightnessValue').textContent=b+'%';$('imageContrastValue').textContent=c+'%';$('zoomValue').textContent=z.toFixed(1)+'×';}
async function loadImage(file,request){if(file.size>20*1024*1024)throw Error('Choose an image smaller than 20 MB.');const header=new Uint8Array(await file.slice(0,12).arrayBuffer());const png=[137,80,78,71,13,10,26,10].every((v,i)=>header[i]===v),jpeg=header[0]===255&&header[1]===216&&header[2]===255,webp=String.fromCharCode(...header.slice(0,4))==='RIFF'&&String.fromCharCode(...header.slice(8,12))==='WEBP';if(!png&&!jpeg&&!webp)throw Error('Choose a valid PNG, JPG, or WebP image.');const url=URL.createObjectURL(file),img=new Image();try{img.src=url;await img.decode();let sourceMatch=false;if(file.size===83753){const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());sourceMatch=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('')==='8a6c540ab35554e4a2565568d3699ec68cb94c3fc819af082b18c609eef71076';}if(img.naturalWidth>8192||img.naturalHeight>8192||img.naturalWidth*img.naturalHeight>24000000)throw Error('Use an image up to 8192 pixels per side and 24 megapixels total.');if(request!==loadSequence){URL.revokeObjectURL(url);return;}clearImage();scan=null;if(current&&current!==demo)dispose(current);setCurrent(null);imageState={url,width:img.naturalWidth,height:img.naturalHeight,name:file.name};publishedCase=sourceMatch;$('imagePreview').src=url;$('imageName').textContent=file.name;real=true;resetImage();presentImage();$('status').classList.remove('error');$('status').textContent=img.naturalWidth+' × '+img.naturalHeight+' pixels · opened locally as a 2D image. No diagnostic analysis was performed.';renderPublishedCase();}catch(e){URL.revokeObjectURL(url);if(e.message.includes('8192'))throw e;throw Error('This image could not be opened. Choose a valid PNG, JPG, or WebP image.');}}
function presentImage(){setCurrent(null);$('scanActions').hidden=true;$('imageActions').hidden=false;$('slices').hidden=true;showImage(true);$('mode').textContent='YOUR IMAGE · 2D VIEW ONLY';$('viewLabel').textContent='Image / 2D viewer';$('geometryState').textContent='LOCAL IMAGE';$('geometryNote').textContent='Single image · no 3D reconstruction or diagnostic analysis';document.querySelector('.orientation>span').textContent='IMAGE PREVIEW';renderPublishedCase();}
function exportImage(){const img=$('imagePreview'),canvas=document.createElement('canvas'),scale=Math.min(1,4096/Math.max(imageState.width,imageState.height));canvas.width=Math.round(imageState.width*scale);canvas.height=Math.round(imageState.height*scale);const ctx=canvas.getContext('2d');ctx.filter='brightness('+$('imageBrightness').value+'%) contrast('+$('imageContrast').value+'%)';ctx.drawImage(img,0,0,canvas.width,canvas.height);canvas.toBlob(blob=>{if(!blob)return toast('Unable to export this image.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cortex-image-preview.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Image exported as PNG.');});}
for(const id of ['imageBrightness','imageContrast','imageZoom'])$(id).oninput=updateImage;$('removeImage').onclick=()=>$('clear').click();

function exitPublishedCase(){publishedCase=false;$('publishedCaseActions').hidden=true;$('publishedCaseDetails').hidden=true;$('drop').hidden=false;if(imageState)$('imageActions').hidden=false;}
function renderPublishedCase(){if(!publishedCase)return;$('publishedCaseActions').hidden=false;$('imageActions').hidden=true;$('drop').hidden=true;$('mode').textContent='PUBLISHED MRI EXAMPLE';$('viewLabel').textContent='Control / MCI / Alzheimer’s';$('geometryNote').textContent='Published comparison · source labels, not automated diagnoses';$('status').textContent='Open-access educational figure. Select “View published diagnosis” to read the source label.';}
$('loadPublishedCase').onclick=async()=>{const button=$('loadPublishedCase'),before=loadSequence;button.disabled=true;try{const response=await fetch('assets/alzheimers-published-example.jpg');if(!response.ok)throw Error('Could not load the published example.');const blob=await response.blob();if(before!==loadSequence)return;await load(new File([blob],'published-alzheimers-example.jpg',{type:'image/jpeg'}));if(imageState?.name==='published-alzheimers-example.jpg'&&loadSequence===before+1){publishedCase=true;renderPublishedCase();}}catch(e){$('status').textContent=e.message;}finally{button.disabled=false;}};
$('showPublishedCase').onclick=()=>{$('publishedCaseDetails').hidden=false;};$('replacePublishedCase').onclick=()=>$('file').click();$('removePublishedCase').onclick=()=>$('clear').click();
